import{_ as d,o as a,c as e,aw as r}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"3 утверждения","description":"","frontmatter":{},"headers":[],"relativePath":"js/js-task/algoritms/three-statements.md","filePath":"wiki/dev-commit/js/js-task/algoritms/three-statements.md"}'),s={name:"js/js-task/algoritms/three-statements.md"};function l(o,t,i,n,h,p){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="_3-утверждения" tabindex="-1">3 утверждения <a class="header-anchor" href="#_3-утверждения" aria-label="Permalink to &quot;3 утверждения&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ul><li>Проверить код</li></ul></div><h2 id="задача" tabindex="-1">Задача <a class="header-anchor" href="#задача" aria-label="Permalink to &quot;Задача&quot;">​</a></h2><p>Даны 3 утверждения:</p><ol><li>В коде больше 10 багов</li><li>В коде меньше 10 багов</li><li>В коде наверняка есть один баг</li></ol><p>Если истинно только одно утверждение - сколько багов в коде?</p><h2 id="ответ" tabindex="-1">Ответ <a class="header-anchor" href="#ответ" aria-label="Permalink to &quot;Ответ&quot;">​</a></h2><p><strong>Ответ: 0 багов.</strong></p><p>Ниже перебор вариантов. Пусть N — число багов.</p><table tabindex="0"><thead><tr><th>N</th><th>1. «больше 10»</th><th>2. «меньше 10»</th><th>3. «есть один баг»</th><th>Сколько истинных</th></tr></thead><tbody><tr><td>0</td><td>ложь</td><td><strong>истина</strong></td><td>ложь</td><td><strong>1</strong> ✅</td></tr><tr><td>1</td><td>ложь</td><td>истина</td><td>истина</td><td>2 ❌</td></tr><tr><td>2–9</td><td>ложь</td><td>истина</td><td>ложь (если «ровно один»)</td><td>1 ✅ ⚠️</td></tr><tr><td>10</td><td>ложь</td><td>ложь</td><td>ложь / истина</td><td>0 или 1</td></tr><tr><td>&gt;10</td><td>истина</td><td>ложь</td><td>истина (если «хотя бы один»)</td><td>2 ❌</td></tr></tbody></table><p>Ответ зависит от того, как понимать третье утверждение.</p><p><strong>Если «есть один баг» значит «хотя бы один»</strong> (так обычно и понимают «наверняка есть баг»):</p><ul><li>Утверждения 1 и 2 не могут быть истинными одновременно. При N ≠ 10 одно из них истинно, значит третье должно быть ложным, то есть N = 0. Проверяем: 0 &lt; 10 — истина, остальные ложны ✅</li><li>Особый случай N = 10: первые два ложны, третье истинно. Это тоже ровно одно истинное утверждение ✅</li></ul><p><strong>Если «есть один баг» значит «ровно один»:</strong></p><ul><li>N = 0 подходит: истинно только второе утверждение.</li><li>Но подходят и N от 2 до 9: истинно только второе, а третье ложно.</li><li>N = 10 не подходит: все три утверждения ложны.</li></ul><p>Только N = 0 подходит при любом прочтении, поэтому это и есть задуманный ответ: <strong>в коде нет багов</strong>. Подвох в том, что фраза «наверняка есть баг» оказывается ложью.</p><p>Если строго понимать третье утверждение как «хотя бы один баг», то 10 тоже даёт ровно одно истинное утверждение.</p>',17)])])}const _=d(s,[["render",l]]);export{m as __pageData,_ as default};
